tion` npm package\r\n- `AppConfigurationClient` constructor with connection string\r\n- `setConfigurationSetting()` with key, value, label\r\n- `getConfigurationSetting()` by key and label\r\n- `listConfigurationSettings()` with `ListConfigurationSettingOptions`\r\n- Feature flag settings with `featureFlagContentType`\r\n- `deleteConfigurationSetting()` and `RestError` handling\r\n- Async iteration with `for await...of` pattern\n\n## Generated Code\n\n### appConfiguration.ts\n```\nimport {\r\n  AppConfigurationClient,\r\n  featureFlagContentType,\r\n  type FeatureFlagValue,\r\n} from \"@azure/app-configuration\";\r\nimport { RestError } from \"@azure/core-rest-pipeline\";\r\n\r\nconst connectionString = process.env.AZURE_APP_CONFIGURATION_CONNECTION_STRING;\r\n\r\nif (!connectionString) {\r\n  throw new Error(\r\n    \"Set AZURE_APP_CONFIGURATION_CONNECTION_STRING before running this example.\",\r\n  );\r\n}\r\n\r\nconst client = new AppConfigurationClient(connectionString);\r\nconst key = \"app:Settings:FontSize\";\r\nconst productionLabel = \"Production\";\r\n\r\nasync function main(): Promise\u003cvoid\u003e {\r\n  try {\r\n    await client.setConfigurationSetting({\r\n      key,\r\n      value: \"24\",\r\n    });\r\n\r\n    await client.setConfigurationSetting({\r\n      key,\r\n      label: productionLabel,\r\n      value: \"24\",\r\n    });\r\n\r\n    const setting = await client.getConfigurationSetting({ key });\r\n    console.log(`Value for \"${key}\": ${setting.value ?? \"\u003cno value\u003e\"}`);\r\n\r\n    console.log('Settings matching \"app:Settings:*\":');\r\n    for await (const item of client.listConfigurationSettings({\r\n      keyFilter: \"app:Settings:*\",\r\n    })) {\r\n      const label = item.label ? ` [${item.label}]` : \"\";\r\n      console.log(`- ${item.key}${label} = ${item.value ?? \"\u003cno value\u003e\"}`);\r\n    }\r\n\r\n    const betaFeatureFlag: FeatureFlagValue = {\r\n      enabled: true,\r\n      description: \"Enables the beta feature experience.\",\r\n      conditions: {\r\n        clientFilters: [],\r\n      },\r\n    };\r\n\r\n    await client.setConfigurationSetting({\r\n      key: \"BetaFeature\",\r\n      contentType: featureFlagContentType,\r\n      value: betaFeatureFlag,\r\n    });\r\n\r\n    console.log('Created feature flag \"BetaFeature\".');\r\n\r\n    await client.deleteConfigurationSetting({ key });\r\n    console.log(`Deleted setting \"${key}\".`);\r\n  } catch (error: unknown) {\r\n    if (error instanceof RestError) {\r\n      console.error(`Azure App Configuration request failed: ${error.message}`);\r\n\r\n      if (error.statusCode !== undefined) {\r\n        console.error(`Status code: ${error.statusCode}`);\r\n      }\r\n    } else if (error instanceof Error) {\r\n      console.error(`Unexpected error: ${error.message}`);\r\n    } else {\r\n      console.error(\"Unexpected non-Error failure:\", error);\r\n    }\r\n\r\n    process.exitCode = 1;\r\n  }\r\n}\r\n\r\nvoid main();\r\n\n```\n\n### package-lock.json\n```\n{\r\n  \"name\": \"hyoka-app-configuration-dp-js-ts-crud-baseline-skills-gpt-5.4-4290457304\",\r\n  \"version\": \"1.0.0\",\r\n  \"lockfileVersion\": 3,\r\n  \"requires\": true,\r\n  \"packages\": {\r\n    \"\": {\r\n      \"name\": \"hyoka-app-configuration-dp-js-ts-crud-baseline-skills-gpt-5.4-4290457304\",\r\n      \"version\": \"1.0.0\",\r\n      \"license\": \"ISC\",\r\n      \"dependencies\": {\r\n        \"@azure/app-configuration\": \"^1.11.0\"\r\n      },\r\n      \"devDependencies\": {\r\n        \"@types/node\": \"^25.6.0\",\r\n        \"typescript\": \"^6.0.3\"\r\n      }\r\n    },\r\n    \"node_modules/@azure/abort-controller\": {\r\n      \"version\": \"2.1.2\",\r\n      \"resolved\": \"https://registry.npmjs.org/@azure/abort-controller/-/abort-controller-2.1.2.tgz\",\r\n      \"integrity\": \"sha512-nBrLsEWm4J2u5LpAPjxADTlq3trDgVZZXHNKabeXZtpq3d3AbN/KGO82R87rdDz5/lYB024rtEf10/q0urNgsA==\",\r\n      \"license\": \"MIT\",\r\n      \"dependenci